function editorPanelViews(){return`<section class="org-studio-panel-view" id="org-panel-people" role="tabpanel" ${editorTab==='people'?'':'hidden'}><div class="org-studio-section-head"><div><h2>Personas</h2><p>${current.people.length} en la estructura</p></div><button class="btn btn-secondary btn-sm" onclick="orgChartAddPerson('')">${siIcon?.('plus',14)||''} Nivel principal</button></div><div class="org-person-list">${ordered().map(personEditor).join('')}</div></section><section class="org-studio-panel-view" id="org-panel-details" role="tabpanel" ${editorTab==='details'?'':'hidden'}><div class="org-studio-section-head"><div><h2>Datos del organigrama</h2><p>Define cómo se identifica esta estructura.</p></div></div><div class="org-form-section"><label>Título<input class="control-input" value="${attr(current.title)}" oninput="orgChartSet('title',this.value)"></label><label>Alcance<input class="control-input" value="${attr(current.scope)}" placeholder="Ej. Marketing regional" oninput="orgChartSet('scope',this.value)"></label><label>Descripción<textarea class="control-input" rows="4" placeholder="Contexto opcional" oninput="orgChartSet('description',this.value)">${escape(current.description)}</textarea></label></div></section><section class="org-studio-panel-view" id="org-panel-areas" role="tabpanel" ${editorTab==='areas'?'':'hidden'}><div class="org-studio-section-head"><div><h2>Áreas</h2><p>Identifica equipos con matices suaves SIERRA.</p></div><button class="btn btn-secondary btn-sm" onclick="orgChartAreaAdd()">${siIcon?.('plus',14)||''} Crear área</button></div><div class="org-area-list">${current.areas.length?current.areas.map(areaEditor).join(''):'<div class="org-panel-empty"><strong>Sin áreas todavía</strong><span>Créala aquí y asígnala desde Personas.</span></div>'}</div></section><section class="org-studio-panel-view" id="org-panel-import" role="tabpanel" ${editorTab==='import'?'':'hidden'}><div class="org-studio-section-head"><div><h2>Importar estructura</h2><p>Previsualiza y valida antes de reemplazar.</p></div></div><div class="org-form-section"><label class="org-upload">${siIcon?.('file-spreadsheet',22)||''}<strong>Importar Excel o CSV</strong><span>Selecciona un archivo estructurado de hasta 1,000 personas.</span><input type="file" accept=".xlsx,.xls,.csv" onchange="orgChartImportFile(this)"></label><button class="btn btn-secondary" onclick="orgChartDownloadTemplate()">${siIcon?.('download',15)||''} Descargar plantilla CSV</button><div class="org-import-guide"><strong>Columnas admitidas</strong><span>ID · Nombre · Puesto · Área · Jefe ID · Tipo · Reporte indirecto ID · Email</span><small>El archivo se procesa localmente y no se envía a un servicio externo.</small></div></div></section><section class="org-studio-panel-view" id="org-panel-media" role="tabpanel" ${editorTab==='media'?'':'hidden'}><div class="org-studio-section-head"><div><h2>Banco de retratos</h2><p>Sube una vez, arrastra y ajusta el encuadre.</p></div></div>${resourceBank()}</section><section class="org-studio-panel-view" id="org-panel-recovery" role="tabpanel" ${editorTab==='recovery'?'':'hidden'}><div class="org-studio-section-head"><div><h2>Versiones y recuperación</h2><p>Respalda, compara y recupera con seguridad.</p></div></div>${scenariosHtml()}<section class="org-directory-note"><span>${siIcon?.('cloud',18)||''}</span><div><strong>Directorio vinculado</strong><p>Preparado como propuesta sin conexión. No se transmite información ni se solicitan permisos.</p></div><button class="btn btn-secondary btn-sm" disabled>Requiere aprobación</button></section></section>`}
window.orgChartEditorTab=function(tab,button){if(!ORG_EDITOR_TABS.some(item=>item[0]===tab))return;editorTab=tab;document.querySelectorAll('.org-studio-rail [role="tab"]').forEach(item=>{const selected=item===button;item.classList.toggle('is-selected',selected);item.setAttribute('aria-selected',String(selected))});document.querySelectorAll('.org-studio-panel-view').forEach(view=>view.hidden=view.id!==`org-panel-${tab}`);const heading=document.querySelector(`#org-panel-${tab} h2`);heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})};
