function renderEditor(){if(!current)return;const stage=document.querySelector('.org-builder-stage'),scroll={left:stage?.scrollLeft||0,top:stage?.scrollTop||0};document.getElementById('sec-title').textContent=current.title||'Organigrama';document.getElementById('sec-sub').textContent='Editor de estructura organizacional';setSecCrumbs?.([{label:'Organigramas',onclick:'orgChartBack()'},{label:current.title||'Sin título'}]);document.getElementById('pg').innerHTML=`<div class="org-builder ${editorPanelOpen?'':'is-panel-collapsed'}"><aside class="org-studio-rail"><nav role="tablist" aria-label="Herramientas del organigrama">${ORG_EDITOR_TABS.map(editorTabButton).join('')}</nav><button type="button" data-org-panel-toggle aria-expanded="${editorPanelOpen}" aria-label="${editorPanelOpen?'Ocultar herramientas':'Mostrar herramientas'}" onclick="orgChartTogglePanel()">${siIcon?.(editorPanelOpen?'chevron-left':'chevron-right',18)||''}<span>Panel</span></button></aside><section class="org-builder-panel" aria-label="Panel de edición"><div class="org-builder-form">${editorPanelViews()}</div></section><section class="org-builder-preview"><header><div class="org-workspace-title"><strong>${escape(current.title||'Organigrama')}</strong><span id="org-chart-save-state">Guardado</span></div><div class="org-workspace-actions"><button class="icon-btn icon-btn-quiet" data-org-panel-toggle aria-expanded="${editorPanelOpen}" aria-label="${editorPanelOpen?'Ocultar herramientas':'Mostrar herramientas'}" onclick="orgChartTogglePanel()">${siIcon?.('columns',16)||''}</button><button class="btn btn-primary btn-sm" onclick="orgChartExportOpen()">${siIcon?.('download',15)||''} Exportar</button></div></header><div class="org-builder-stage" aria-label="Lienzo libre del organigrama"><div id="org-chart-preview">${preview()}</div></div></section></div>`;current.areas.forEach((_,index)=>window[`orgAreaColor${index}`]=value=>orgChartAreaSet(index,'color',value,true));installPersonCallbacks();(window.requestAnimationFrame||window.setTimeout)(()=>{drawIndirectLines();const next=document.querySelector('.org-builder-stage');if(typeof next?.scrollTo==='function')next.scrollTo(scroll)})}
function refresh(){const host=document.getElementById('org-chart-preview');if(host){host.innerHTML=preview();(window.requestAnimationFrame||window.setTimeout)(()=>drawIndirectLines())}const title=document.getElementById('sec-title');if(title)title.textContent=current?.title||'Organigrama'}
window.showOrgChartBuilder=function(){syncModule('comunicaciones');_navLeaf='comunicaciones|_|org-charts';sessionStorage.setItem('sierra_route','module:comunicaciones:org-charts');leaveView();renderSidebarTree();document.getElementById('tb-section').textContent='Marketing';document.getElementById('product-controls').style.display='none';load();renderLibrary();syncCloudLibrary()};
window.orgChartBack=async function(){clearTimeout(saveTimer);persist();await window.SierraOrgChartTeam?.leave?.();renderLibrary();syncCloudLibrary()};
window.orgChartNew=function(){current=chart();charts.unshift(current);persist();renderEditor();publish(current)};window.orgChartOpen=async id=>{const item=charts.find(entry=>entry.id===id)||null;if(!item)return;current=item;renderEditor();if(item.cloudId&&window.SierraOrgChartTeam)try{status('Abriendo versión compartida…');const result=await window.SierraOrgChartTeam.open(item.cloudId);current=chart({...result.draft,cloudId:item.cloudId,cloudRole:result.role});const index=charts.findIndex(entry=>entry.id===item.id||entry.cloudId===item.cloudId);if(index>=0)charts[index]=current;persist();renderEditor();status('Guardado en línea')}catch(error){toast?.(error.message||'No se pudo abrir la versión compartida. Se conserva la copia local.')}};
window.orgChartDuplicate=function(id){const source=charts.find(item=>item.id===id);if(!source)return;const copy=chart(structuredClone(source)),map=new Map(copy.people.map(item=>[item.uid,`person-${uid()}`]));copy.id=uid();copy.cloudId='';copy.cloudRole='';copy.title=`${source.title} · copia`;copy.people.forEach(item=>{const old=item.uid;item.uid=map.get(old);item.parent=map.get(item.parent)||'';item.indirectParents=item.indirectParents.map(parent=>map.get(parent)).filter(Boolean)});copy.createdAt=copy.updatedAt=new Date().toISOString();charts.unshift(copy);persist();renderLibrary();publish(copy)};
window.orgChartDelete=async function(id){const item=charts.find(entry=>entry.id===id);if(!item||!confirm(`¿Eliminar “${item.title}”? Esta acción no modifica los Memos donde ya se utilizó.`))return;if(item.cloudId&&window.SierraOrgChartTeam)try{const opened=await window.SierraOrgChartTeam.open(item.cloudId);item.archived=true;window.SierraOrgChartTeam.capture({...opened.draft,archived:true});await window.SierraOrgChartTeam.leave()}catch{}charts=charts.filter(entry=>entry.id!==id);persist();renderLibrary()};
window.orgChartImportMemo=function(id){const source=memoSources().find(item=>item.id===id);if(!source)return;const imported=chart({title:source.title,scope:`Importado de ${source.source}`,people:structuredClone(source.people)}),map=new Map(source.people.map((item,index)=>[item.uid,imported.people[index].uid]));imported.people.forEach((item,index)=>item.parent=map.get(source.people[index].parent)||'');charts.unshift(imported);persist();renderLibrary();publish(imported);toast?.('Organigrama guardado en la biblioteca')};
window.orgChartSet=function(key,value,structural=false){if(!current)return;current[key]=value;schedule();structural?renderEditor():refresh()};window.orgChartPersonSet=function(index,key,value,structural=false){const item=current?.people[index];if(!item)return;item[key]=value;if(key==='parent')item.indirectParents=item.indirectParents.filter(parent=>parent!==value);if(key==='areaId')item.department=current.areas.find(entry=>entry.id===value)?.name||'';schedule();structural?renderEditor():refresh()};
window.orgChartAddPerson=function(parent=''){if(!current)return;current.people.push(person({parent},current.people.length));schedule();renderEditor()};window.orgChartRemovePerson=function(index){if(!current||current.people.length<=1){toast?.('El organigrama necesita al menos una persona.');return}const removed=current.people[index];current.people.splice(index,1);current.people.forEach(item=>{if(item.parent===removed.uid)item.parent='';item.indirectParents=item.indirectParents.filter(parent=>parent!==removed.uid)});schedule();renderEditor()};
window.orgChartAreaAdd=function(){current.areas.push(area({name:`Área ${current.areas.length+1}`},current.areas.length));schedule();renderEditor()};
window.orgChartAreaSet=function(index,key,value,structural=false){const entry=current?.areas[index];if(!entry)return;entry[key]=value;if(key==='name')current.people.filter(item=>item.areaId===entry.id).forEach(item=>item.department=value);schedule();structural?renderEditor():refresh()};
window.orgChartAreaRemove=function(index){const removed=current?.areas[index];if(!removed)return;current.areas.splice(index,1);current.people.forEach(item=>{if(item.areaId===removed.id)item.areaId=''});schedule();renderEditor()};
async function prepareImage(file){if(typeof commsPrepareImageFile==='function')return commsPrepareImageFile(file,{maxDimension:1400,quality:.86});if(!file?.type?.startsWith('image/'))throw Error('Selecciona un archivo de imagen compatible.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)})}
window.orgChartPersonPhoto=async function(index,input){const file=input.files?.[0];if(!file)return;input.disabled=true;try{const src=await prepareImage(file),item=current?.people[index];if(!item)return;Object.assign(item,{photo:src,photoX:50,photoY:50,photoZoom:100});schedule();renderEditor();window.orgChartCropOpen(index)}catch(error){toast?.(error.message||'No se pudo preparar el retrato.')}finally{input.value='';input.disabled=false}};
window.orgChartResourcesAdd=async function(input){const files=[...(input.files||[])].slice(0,30);input.disabled=true;let added=0;try{for(const file of files){try{current.resources.push(resource({name:file.name.replace(/\.[^.]+$/,''),src:await prepareImage(file)}));added++}catch(error){toast?.(`${file.name}: ${error.message||'no se pudo leer'}`)}}if(added){schedule();renderEditor();toast?.(`${added} ${added===1?'retrato agregado':'retratos agregados'} al banco.`)}}finally{input.value='';input.disabled=false}};
window.orgChartResourceRemove=function(index){current.resources.splice(index,1);schedule();renderEditor()};
window.orgChartResourceDrag=function(event,id){event.dataTransfer.setData('text/x-sierra-org-resource',id);event.dataTransfer.effectAllowed='copy'};
window.orgChartResourceDrop=function(event,index){event.preventDefault();const id=event.dataTransfer.getData('text/x-sierra-org-resource'),entry=current.resources.find(item=>item.id===id),target=current.people[index];if(!entry||!target)return;Object.assign(target,{photo:entry.src,photoX:50,photoY:50,photoZoom:100});schedule();renderEditor();window.orgChartCropOpen(index)};
window.orgChartCropOpen=function(index){const item=current?.people[index];if(!item?.photo)return;document.querySelector('.org-crop-dialog')?.close();const dialog=document.createElement('dialog');dialog.className='modal-content org-crop-dialog';dialog.setAttribute('aria-label',`Encuadrar retrato de ${item.name||'persona'}`);dialog.innerHTML=`<div class="modal-header"><div><h2>Encuadrar retrato</h2><p>${escape(item.name||'Persona sin nombre')}</p></div><button class="icon-btn" aria-label="Cerrar">${siIcon?.('x',18)||'×'}</button></div><div class="org-crop-body"><p>Arrastra la imagen para centrarla. También puedes usar las flechas del teclado.</p><span class="org-crop-preview" tabindex="0" aria-label="Vista del retrato; arrastra o usa flechas para ajustar"><img src="${attr(item.photo)}" alt="${attr(item.name)}" style="${photoStyle(item)}"></span><label>Zoom <output>${Math.round(item.photoZoom)}%</output><input type="range" min="100" max="220" step="5" value="${item.photoZoom}"></label><div class="org-crop-actions"><button class="btn btn-secondary" data-reset>Restablecer</button><button class="btn btn-primary" data-done>Listo</button></div></div>`;const previewNode=dialog.querySelector('.org-crop-preview'),range=dialog.querySelector('input'),update=()=>{dialog.querySelector('img').style.cssText=photoStyle(item);dialog.querySelector('output').textContent=`${Math.round(item.photoZoom)}%`;range.value=item.photoZoom;refresh()},move=(dx,dy)=>{item.photoX=Math.max(0,Math.min(100,item.photoX+dx));item.photoY=Math.max(0,Math.min(100,item.photoY+dy));update();schedule()};range.oninput=()=>{item.photoZoom=Number(range.value);update()};range.onchange=schedule;previewNode.onkeydown=event=>{const steps={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]};if(steps[event.key]){event.preventDefault();move(...steps[event.key])}};previewNode.onpointerdown=event=>{event.preventDefault();previewNode.setPointerCapture?.(event.pointerId);cropState={x:event.clientX,y:event.clientY,px:item.photoX,py:item.photoY};previewNode.onpointermove=e=>{if(!cropState)return;const rect=previewNode.getBoundingClientRect();item.photoX=Math.max(0,Math.min(100,cropState.px+(e.clientX-cropState.x)/rect.width*100));item.photoY=Math.max(0,Math.min(100,cropState.py+(e.clientY-cropState.y)/rect.height*100));update()};previewNode.onpointerup=()=>{cropState=null;previewNode.onpointermove=null;schedule()}};dialog.querySelector('.modal-header button').onclick=()=>dialog.close();dialog.querySelector('[data-done]').onclick=()=>dialog.close();dialog.querySelector('[data-reset]').onclick=()=>{Object.assign(item,{photoX:50,photoY:50,photoZoom:100});update();schedule()};dialog.onclose=()=>{schedule();dialog.remove();renderEditor()};document.body.append(dialog);dialog.showModal();previewNode.focus()};
function normalizeHeader(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function rowValue(row,names){const key=Object.keys(row).find(entry=>names.includes(normalizeHeader(entry)));return key?String(row[key]??'').trim():''}
function csvRows(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i],next=text[i+1];if(char==='"'&&quoted&&next==='"'){cell+='"';i++}else if(char==='"')quoted=!quoted;else if(char===','&&!quoted){row.push(cell);cell=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')i++;row.push(cell);if(row.some(value=>value.trim()))rows.push(row);row=[];cell=''}else cell+=char}row.push(cell);if(row.some(value=>value.trim()))rows.push(row);const headers=rows.shift()||[];return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]||''])))}
async function excelRows(file){if(/\.csv$/i.test(file.name))return csvRows(await file.text());if(!window.XLSX)await new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-org-xlsx]');if(existing){existing.addEventListener('load',resolve,{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.dataset.orgXlsx='true';script.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';script.onload=resolve;script.onerror=()=>reject(Error('No se pudo cargar el lector de Excel. Puedes usar la plantilla CSV.'));document.head.append(script)});const book=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheet=book.Sheets[book.SheetNames[0]];return XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false})}
function hasCycle(people){const byId=new Map(people.map(item=>[item.uid,item]));return people.some(start=>{const seen=new Set([start.uid]);let id=start.parent;while(id&&byId.has(id)){if(seen.has(id))return true;seen.add(id);id=byId.get(id).parent}return false})}
