function installCanvasPan(){const stage=document.querySelector('.org-builder-stage');if(!stage||stage.dataset.panReady)return;stage.dataset.panReady='true';let start=null;const finish=event=>{if(!start)return;stage.releasePointerCapture?.(event.pointerId);start=null;stage.classList.remove('is-panning')};stage.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('button,input,select,textarea,a,.org-chart-node'))return;start={x:event.clientX,y:event.clientY,left:stage.scrollLeft,top:stage.scrollTop};stage.setPointerCapture?.(event.pointerId);stage.classList.add('is-panning');event.preventDefault()});stage.addEventListener('pointermove',event=>{if(!start)return;stage.scrollLeft=start.left-(event.clientX-start.x);stage.scrollTop=start.top-(event.clientY-start.y)});stage.addEventListener('pointerup',finish);stage.addEventListener('pointercancel',finish)}
function toolbarPositionKey(){return`sierra_org_toolbar_position:${typeof me!=='undefined'&&me?.id?me.id:'local'}`}
function storedToolbarPosition(){try{const value=JSON.parse(localStorage.getItem(toolbarPositionKey())||'null');return Number.isFinite(value?.x)&&Number.isFinite(value?.y)?{x:Math.max(0,Math.min(1,value.x)),y:Math.max(0,Math.min(1,value.y))}:null}catch{return null}}
function placeToolbar(toolbar,surface,left,top){const width=toolbar.offsetWidth,height=toolbar.offsetHeight,maxLeft=Math.max(8,surface.clientWidth-width-8),header=surface.querySelector(':scope>header')?.offsetHeight||0,maxTop=Math.max(header+8,surface.clientHeight-height-8);toolbar.style.left=`${Math.max(8,Math.min(maxLeft,left))}px`;toolbar.style.top=`${Math.max(header+8,Math.min(maxTop,top))}px`;toolbar.style.right='auto';toolbar.style.bottom='auto';toolbar.style.transform='none'}
function saveToolbarPosition(toolbar,surface){const toolbarRect=toolbar.getBoundingClientRect(),surfaceRect=surface.getBoundingClientRect(),header=surface.querySelector(':scope>header')?.offsetHeight||0,availableX=Math.max(1,surface.clientWidth-toolbar.offsetWidth-16),availableY=Math.max(1,surface.clientHeight-toolbar.offsetHeight-header-16),x=Math.max(0,Math.min(1,(toolbarRect.left-surfaceRect.left-8)/availableX)),y=Math.max(0,Math.min(1,(toolbarRect.top-surfaceRect.top-header-8)/availableY));try{localStorage.setItem(toolbarPositionKey(),JSON.stringify({x,y}))}catch{}}
